def sin(x, **_extra):
    import json, os, datetime, time, math, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0375000" if __import__("os").path.isdir("./environment_mix/0375000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **xtra):
        return {"error": {"code": code, "message": msg, **xtra}}

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return _now_utc().isoformat().replace("+00:00", "Z")

    def _parse_dt(v):
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(v, str) or not v:
            return None
        s = v.strip()
        if s.endswith("Z"):
            s = s[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _day_bucket(dt):
        dt = dt.astimezone(datetime.timezone.utc)
        return datetime.datetime(dt.year, dt.month, dt.day, 0, 0, 0, tzinfo=datetime.timezone.utc)

    def _minute_bucket(dt):
        dt = dt.astimezone(datetime.timezone.utc)
        return datetime.datetime(dt.year, dt.month, dt.day, dt.hour, dt.minute, 0, tzinfo=datetime.timezone.utc)

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _get_request_meta():
        ip = _extra.get("request_ip")
        ua = _extra.get("user_agent")
        return (ip if isinstance(ip, str) else None, ua if isinstance(ua, str) else None)

    # Resolve ambient authentication:
    # - Prefer explicit api_key_id/api_key if passed (even though tool schema doesn't list it).
    # - Otherwise choose any active key that can serve this call.
    api_keys = _load("api_keys.json")
    api_key_param = _extra.get("api_key") or _extra.get("api_key_id") or _extra.get("key") or _extra.get("key_id")

    key_row = None
    if api_key_param is not None:
        if not isinstance(api_key_param, str) or not api_key_param.strip():
            key_row = None
        else:
            token = api_key_param.strip()
            for r in api_keys:
                if r.get("id") == token or r.get("key_prefix") == token:
                    key_row = r
                    break
    else:
        # Ambient: pick any active key.
        for r in api_keys:
            if r.get("status") == "active":
                key_row = r
                break

    operations = _load("calculator_operations.json")
    daily_usage = _load("daily_usage.json")
    buckets = _load("rate_limit_buckets.json")

    start = time.perf_counter()
    now = _now_utc()
    created_at = _iso(now)
    ip, ua = _get_request_meta()

    def _record_op(api_key_id, status, args_obj, result_number=None, result_boolean=None,
                   result_tuple=None, result_complex_tuple=None, error_code=None, error_message=None, duration_ms=None):
        op = {
            "id": _new_id("op"),
            "api_key_id": api_key_id,
            "tool_name": "sin",
            "status": status,
            "args": args_obj,
            "result_number": result_number,
            "result_boolean": result_boolean,
            "result_tuple": result_tuple,
            "result_complex_tuple": result_complex_tuple,
            "error_code": error_code,
            "error_message": error_message,
            "duration_ms": duration_ms,
            "request_ip": ip,
            "user_agent": ua,
            "created_at": created_at,
            "updated_at": created_at,
        }
        operations.append(op)
        _save("calculator_operations.json", operations)
        return op

    def _inc_usage(api_key_id, final_status):
        # Only for authorized (business rule). Caller ensures key is active and exists.
        day = _day_bucket(now)
        day_iso = _iso(day)
        row = None
        for r in daily_usage:
            if r.get("api_key_id") == api_key_id and r.get("usage_date") == day_iso:
                row = r
                break
        if row is None:
            row = {
                "id": _new_id("du"),
                "api_key_id": api_key_id,
                "usage_date": day_iso,
                "request_count": 0,
                "success_count": 0,
                "failed_count": 0,
                "rejected_count": 0,
                "created_at": created_at,
                "updated_at": created_at,
            }
            daily_usage.append(row)
        row["request_count"] = int(row.get("request_count") or 0) + 1
        if final_status == "succeeded":
            row["success_count"] = int(row.get("success_count") or 0) + 1
        elif final_status == "failed":
            row["failed_count"] = int(row.get("failed_count") or 0) + 1
        else:
            row["rejected_count"] = int(row.get("rejected_count") or 0) + 1
        row["updated_at"] = created_at
        _save("daily_usage.json", daily_usage)

    def _check_and_bump_rate(api_key_id, rpm_limit):
        minute = _minute_bucket(now)
        minute_iso = _iso(minute)
        row = None
        for r in buckets:
            if r.get("api_key_id") == api_key_id and r.get("bucket_minute") == minute_iso:
                row = r
                break
        if row is None:
            row = {
                "id": _new_id("rlb"),
                "api_key_id": api_key_id,
                "bucket_minute": minute_iso,
                "request_count": 0,
                "created_at": created_at,
                "updated_at": created_at,
            }
            buckets.append(row)
        cnt = int(row.get("request_count") or 0)
        if cnt + 1 > int(rpm_limit):
            return False
        row["request_count"] = cnt + 1
        row["updated_at"] = created_at
        _save("rate_limit_buckets.json", buckets)
        return True

    def _would_exceed_quota(api_key_id, quota):
        day_iso = _iso(_day_bucket(now))
        for r in daily_usage:
            if r.get("api_key_id") == api_key_id and r.get("usage_date") == day_iso:
                current = int(r.get("request_count") or 0)
                return (current + 1) > int(quota)
        return (0 + 1) > int(quota)

    # If no usable key at all, record as rejected unauthorized using a synthetic api_key_id.
    if not key_row or key_row.get("status") != "active":
        # Choose an id if present; else mark unknown. Still must write an operation row.
        api_key_id = (key_row.get("id") if isinstance(key_row, dict) else None) or "unknown"
        args_obj = {"x": x}
        op = _record_op(api_key_id, "rejected", args_obj, error_code="UNAUTHORIZED", error_message="API key missing/invalid or not active.")
        # update duration
        duration_ms = int((time.perf_counter() - start) * 1000)
        op["duration_ms"] = duration_ms
        op["updated_at"] = _iso(_now_utc())
        _save("calculator_operations.json", operations)
        return _err("UNAUTHORIZED", "Unauthorized: API key missing/invalid or not active.", operation_id=op["id"])

    api_key_id = key_row["id"]

    # Enforce rate limit (before quota per rules order).
    rpm = key_row.get("rate_limit_rpm")
    if not isinstance(rpm, int) or rpm < 1 or rpm > 60000:
        rpm = 60  # fail-safe, but shouldn't happen with valid store
    if not _check_and_bump_rate(api_key_id, rpm):
        args_obj = {"x": x}
        op = _record_op(api_key_id, "rejected", args_obj, error_code="RATE_LIMITED", error_message="Per-minute rate limit exceeded.")
        _inc_usage(api_key_id, "rejected")
        duration_ms = int((time.perf_counter() - start) * 1000)
        op["duration_ms"] = duration_ms
        op["updated_at"] = _iso(_now_utc())
        _save("calculator_operations.json", operations)
        return _err("RATE_LIMIT", "Rate limit exceeded.", operation_id=op["id"])

    # Enforce daily quota.
    quota = key_row.get("daily_request_quota")
    if not isinstance(quota, int) or quota < 0 or quota > 100000000:
        quota = 0
    if _would_exceed_quota(api_key_id, quota):
        args_obj = {"x": x}
        op = _record_op(api_key_id, "rejected", args_obj, error_code="QUOTA_EXCEEDED", error_message="Daily request quota exceeded.")
        _inc_usage(api_key_id, "rejected")
        duration_ms = int((time.perf_counter() - start) * 1000)
        op["duration_ms"] = duration_ms
        op["updated_at"] = _iso(_now_utc())
        _save("calculator_operations.json", operations)
        return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.", operation_id=op["id"])

    # Validate inputs.
    if not isinstance(x, (int, float)) or isinstance(x, bool):
        args_obj = {"x": x}
        op = _record_op(api_key_id, "rejected", args_obj, error_code="VALIDATION_ERROR", error_message="x must be a number.")
        _inc_usage(api_key_id, "rejected")
        duration_ms = int((time.perf_counter() - start) * 1000)
        op["duration_ms"] = duration_ms
        op["updated_at"] = _iso(_now_utc())
        _save("calculator_operations.json", operations)
        return _err("VALIDATION_ERROR", "x must be a number.", operation_id=op["id"])

    # Execute.
    try:
        result = math.sin(float(x))
    except Exception:
        args_obj = {"x": x}
        op = _record_op(api_key_id, "failed", args_obj, error_code="INTERNAL_ERROR", error_message="Computation failed.")
        _inc_usage(api_key_id, "failed")
        duration_ms = int((time.perf_counter() - start) * 1000)
        op["duration_ms"] = duration_ms
        op["updated_at"] = _iso(_now_utc())
        _save("calculator_operations.json", operations)
        return _err("INTERNAL_ERROR", "Computation failed.", operation_id=op["id"])

    args_obj = {"x": float(x)}
    op = _record_op(api_key_id, "succeeded", args_obj, result_number=result)
    _inc_usage(api_key_id, "succeeded")

    # Update key last_used_at only on successful request using this key.
    key_row["last_used_at"] = created_at
    key_row["updated_at"] = created_at
    _save("api_keys.json", api_keys)

    duration_ms = int((time.perf_counter() - start) * 1000)
    op["duration_ms"] = duration_ms
    op["updated_at"] = _iso(_now_utc())
    _save("calculator_operations.json", operations)

    return {
        "operation_id": op["id"],
        "tool_name": "sin",
        "args": op["args"],
        "status": op["status"],
        "result": result,
        "duration_ms": duration_ms,
        "api_key_id": api_key_id,
    }

