            "created_at": _dt_iso(now),
            "updated_at": _dt_iso(now),
        }
        usage.append(du)
    if int(du.get("request_count", 0)) + 1 > quota:
        return _log_and_return(
            ops, usage, buckets, api_keys, key,
            {"a": a, "b": b},
            "rejected",
            error_code="QUOTA_EXCEEDED",
            error_message="Daily request quota exceeded."
        )

    if a == 0 and b == 0:
        return _log_and_return(
            ops, usage, buckets, api_keys, key,
            {"a": a, "b": b},
            "failed",
            error_code="INVALID_LCM",
            error_message="lcm(0, 0) is undefined."
        )

    import math
    res = abs(a // math.gcd(a, b) * b)
    latency = int((datetime.datetime.utcnow() - start).total_seconds() * 1000)
    return _log_and_return(
        ops, usage, buckets, api_keys, key,
        {"a": a, "b": b},
        "succeeded",
        result_number=int(res),
        duration_ms=latency
    )

