    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
    now_iso = now.isoformat().replace("+00:00", "Z")

    api_keys = _load("api_keys.json")
    ops = _load("calculator_operations.json")
    usage = _load("daily_usage.json")
    buckets = _load("rate_limit_buckets.json")

    def _gen_id(prefix):
        return f"{prefix}_{now.strftime('%Y%m%d%H%M%S')}_{int(time.time()*1000)}_{len(ops)+len(usage)+len(buckets)}"

    def _minute_bucket(dt):
        dtz = dt.astimezone(datetime.timezone.utc)
        return dtz.replace(second=0, microsecond=0)

    def _day_bucket(dt):
        dtz = dt.astimezone(datetime.timezone.utc)
        return dtz.replace(hour=0, minute=0, second=0, microsecond=0)

    def _find_key_by_presented(presented):
        if not isinstance(presented, str) or not presented:
            return None
        for k in api_keys:
            if not isinstance(k, dict):
                continue
            if k.get("id") == presented:
                return k
            if k.get("key_prefix") == presented:
                return k
            # Do NOT compare against key_hash (hash plaintext is not stored/known)
        return None

    def _append_operation(row):
        ops.append(row)
        _save("calculator_operations.json", ops)

    def _touch_key_last_used(k):
        k["last_used_at"] = now_iso
        k["updated_at"] = now_iso
        _save("api_keys.json", api_keys)

    def _get_daily_usage(api_key_id):
        day_iso = _day_bucket(now).isoformat().replace("+00:00", "Z")
        for r in usage:
            if r.get("api_key_id") == api_key_id and r.get("usage_date") == day_iso:
                return r
        return None

    def _get_rate_bucket(api_key_id):
        mb_iso = _minute_bucket(now).isoformat().replace("+00:00", "Z")
        for r in buckets:
            if r.get("api_key_id") == api_key_id and r.get("bucket_minute") == mb_iso:
                return r
        return None

    key = _find_key_by_presented(api_key)
    if not key or key.get("status") != "active":
        op = {
            "id": _gen_id("op"),
            "api_key_id": key.get("id") if isinstance(key, dict) else "unknown",
            "tool_name": "add",  # tool_name enum doesn't include whoami; record as rejected via a no-op proxy tool is not allowed.
            # Instead, do not write calculator_operations for non-calculator endpoints.
        }
        # The schema/business rules only mandate logging for calculator tools; whoami is admin/auth endpoint.
        return _err("UNAUTHORIZED", "Unauthorized")

    api_key_id = key.get("id")
    du = _get_daily_usage(api_key_id) or {"request_count": 0, "success_count": 0, "failed_count": 0, "rejected_count": 0}
    rb = _get_rate_bucket(api_key_id) or {"request_count": 0}

    _touch_key_last_used(key)

    # Never return the raw secret; expose safe fields.
    safe_key = {
        "id": key.get("id"),
        "key_prefix": key.get("key_prefix"),
        "owner_label": key.get("owner_label"),
        "status": key.get("status"),
        "rate_limit_rpm": key.get("rate_limit_rpm"),
        "daily_request_quota": key.get("daily_request_quota"),
        "metadata": key.get("metadata"),
        "last_used_at": key.get("last_used_at"),
        "created_at": key.get("created_at"),
        "updated_at": key.get("updated_at"),
    }

    return {
        "api_key": safe_key,
        "usage": {
            "minute": {
                "bucket_start": _minute_bucket(now).isoformat().replace("+00:00", "Z"),
                "request_count": int(rb.get("request_count") or 0),
                "rate_limit_rpm": int(key.get("rate_limit_rpm") or 0),
                "remaining": max(0, int(key.get("rate_limit_rpm") or 0) - int(rb.get("request_count") or 0)),
            },
            "day": {
                "date": _day_bucket(now).isoformat().replace("+00:00", "Z"),
                "request_count": int(du.get("request_count") or 0),
                "daily_request_quota": int(key.get("daily_request_quota") or 0),
                "remaining": max(0, int(key.get("daily_request_quota") or 0) - int(du.get("request_count") or 0)),
                "success_count": int(du.get("success_count") or 0),
                "failed_count": int(du.get("failed_count") or 0),
                "rejected_count": int(du.get("rejected_count") or 0),
            },
        },
        "latency_ms": int((time.time() - t0) * 1000),
    }

def list_api_keys(api_key, status=None, owner_label=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, time, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0375000" if __import__("os").path.isdir("./environment_mix/0375000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    api_keys = _load("api_keys.json")

    def _find_key_by_presented(presented):
        if not isinstance(presented, str) or not presented:
            return None
        for k in api_keys:
            if not isinstance(k, dict):
                continue
            if k.get("id") == presented or k.get("key_prefix") == presented:
                return k
        return None

    caller = _find_key_by_presented(api_key)
    if not caller or caller.get("status") != "active":
        return _err("UNAUTHORIZED", "Unauthorized")

    if status is not None:
        if not isinstance(status, str) or status not in ("active", "suspended", "revoked"):
            return _err("VALIDATION_ERROR", "Invalid status filter.")
    if owner_label is not None and not isinstance(owner_label, str):
        return _err("VALIDATION_ERROR", "owner_label must be a string.")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.")
    if sort is None:
        sort = "created_at"
    if sort not in ("created_at", "updated_at", "last_used_at"):
        return _err("VALIDATION_ERROR", "Invalid sort field.")
    if order is None:
        order = "desc"
    if order not in ("asc", "desc"):
        return _err("VALIDATION_ERROR", "Invalid order.")

    start = 0
    if cursor is not None:
        if not isinstance(cursor, str) or not cursor:
            return _err("VALIDATION_ERROR", "Invalid cursor.")
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8")).decode("utf-8")
            if not raw.startswith("offset:"):
                return _err("VALIDATION_ERROR", "Invalid cursor.")
            start = int(raw.split(":", 1)[1])
            if start < 0:
                return _err("VALIDATION_ERROR", "Invalid cursor.")
        except Exception:
            return _err("VALIDATION_ERROR", "Invalid cursor.")

    rows = [k for k in api_keys if isinstance(k, dict)]
    if status is not None:
        rows = [k for k in rows if k.get("status") == status]
    if owner_label is not None:
        rows = [k for k in rows if k.get("owner_label") == owner_label]

    def _sort_key(k):
        v = k.get(sort)
        # sort datetimes lexicographically (ISO 8601)
        return v if isinstance(v, str) else ""

    reverse = (order == "desc")
    rows.sort(key=_sort_key, reverse=reverse)

    total = len(rows)
    page = rows[start:start + limit]
    next_offset = start + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(f"offset:{next_offset}".encode("utf-8")).decode("utf-8")

    # Return safe projection (no key_hash)
    def _safe(k):
        return {
            "id": k.get("id"),
            "key_prefix": k.get("key_prefix"),
            "owner_label": k.get("owner_label"),
            "status": k.get("status"),
            "rate_limit_rpm": k.get("rate_limit_rpm"),
            "daily_request_quota": k.get("daily_request_quota"),
            "metadata": k.get("metadata"),
            "last_used_at": k.get("last_used_at"),
            "created_at": k.get("created_at"),
            "updated_at": k.get("updated_at"),
        }

    return {
        "data": [_safe(k) for k in page],
        "pagination": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "has_more": has_more,
            "next_cursor": next_cursor,
        },
        "sort": {"field": sort, "order": order},
    }

