def create_api_key(api_key, owner_label, rate_limit_rpm, daily_request_quota, metadata=None, **_extra):
    import json, os, datetime, secrets, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0375000" if __import__("os").path.isdir("./environment_mix/0375000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
            else:
                s2 = s
            return datetime.datetime.fromisoformat(s2)
        except Exception:
            return None

    def _sha256_hex(s):
        return hashlib.sha256(s.encode("utf-8")).hexdigest()

    def _gen_id(prefix):
        return f"{prefix}_{secrets.token_hex(12)}"

    # Validate inputs
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")
    if not isinstance(owner_label, str) or not owner_label.strip():
        return _err("VALIDATION_ERROR", "owner_label must be a non-empty string")
    if not isinstance(rate_limit_rpm, int) or rate_limit_rpm < 1 or rate_limit_rpm > 60000:
        return _err("VALIDATION_ERROR", "rate_limit_rpm must be an integer between 1 and 60000")
    if not isinstance(daily_request_quota, int) or daily_request_quota < 1 or daily_request_quota > 100000000:
        return _err("VALIDATION_ERROR", "daily_request_quota must be an integer between 1 and 100000000")
    if metadata is not None and not isinstance(metadata, dict):
        return _err("VALIDATION_ERROR", "metadata must be an object")

    api_keys = _load("api_keys.json")

    # Authenticate (by matching client-provided credential to stored id or key_prefix)
    caller = None
    api_key_trim = api_key.strip()
    for row in api_keys:
        if row.get("id") == api_key_trim or row.get("key_prefix") == api_key_trim:
            caller = row
            break
    if not caller or caller.get("status") != "active":
        return _err("UNAUTHORIZED", "API key is not authenticated or not active")

    # Create raw key (one-time) and store hash (plaintext not stored)
    raw_key = "sk_" + secrets.token_urlsafe(32)
    key_hash = _sha256_hex(raw_key)
    key_prefix = raw_key[:10]

    # Enforce uniqueness constraints
    for row in api_keys:
        if row.get("key_hash") == key_hash:
            return _err("CONFLICT", "Generated API key collided; retry", field="key_hash")
        if row.get("key_prefix") == key_prefix:
            return _err("CONFLICT", "Generated API key prefix collided; retry", field="key_prefix")

    now = _now()
    new_row = {
        "id": _gen_id("key"),
        "key_hash": key_hash,
        "key_prefix": key_prefix,
        "owner_label": owner_label,
        "status": "active",
        "rate_limit_rpm": rate_limit_rpm,
        "daily_request_quota": daily_request_quota,
        "metadata": metadata if metadata is not None else None,
        "last_used_at": None,
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }
    api_keys.append(new_row)
    _save("api_keys.json", api_keys)

    return {
        "api_key_record": new_row,
        "raw_api_key": raw_key,
    }

def update_api_key(api_key, id, owner_label=None, metadata=None, rate_limit_rpm=None, daily_request_quota=None, status=None, **_extra):
    import json, os, datetime

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0375000" if __import__("os").path.isdir("./environment_mix/0375000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.isoformat().replace("+00:00", "Z")

    # Validate inputs
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")
    if not isinstance(id, str) or not id.strip():
        return _err("VALIDATION_ERROR", "id must be a non-empty string")

    if owner_label is not None and (not isinstance(owner_label, str) or not owner_label.strip()):
        return _err("VALIDATION_ERROR", "owner_label must be a non-empty string when provided")
    if metadata is not None and not isinstance(metadata, dict):
        return _err("VALIDATION_ERROR", "metadata must be an object when provided")
    if rate_limit_rpm is not None:
        if not isinstance(rate_limit_rpm, int) or rate_limit_rpm < 1 or rate_limit_rpm > 60000:
            return _err("VALIDATION_ERROR", "rate_limit_rpm must be an integer between 1 and 60000")
    if daily_request_quota is not None:
        if not isinstance(daily_request_quota, int) or daily_request_quota < 1 or daily_request_quota > 100000000:
            return _err("VALIDATION_ERROR", "daily_request_quota must be an integer between 1 and 100000000")
    if status is not None:
        if status not in ("active", "suspended", "revoked"):
            return _err("VALIDATION_ERROR", "status must be one of: active, suspended, revoked")

    api_keys = _load("api_keys.json")

    # Authenticate caller by id or key_prefix; must be active
    caller = None
    api_key_trim = api_key.strip()
    for row in api_keys:
        if row.get("id") == api_key_trim or row.get("key_prefix") == api_key_trim:
            caller = row
            break
    if not caller or caller.get("status") != "active":
        return _err("UNAUTHORIZED", "API key is not authenticated or not active")

    # Find target key
    target_idx = None
    for i, row in enumerate(api_keys):
        if row.get("id") == id:
            target_idx = i
            break
    if target_idx is None:
        return _err("NOT_FOUND", "API key id not found")

    target = api_keys[target_idx]

    # If status transition requested, enforce lifecycle transitions
    if status is not None and status != target.get("status"):
        transitions = {
            "active": {"suspended", "revoked"},
            "suspended": {"active", "revoked"},
            "revoked": set(),
        }
        cur = target.get("status")
        if cur not in transitions:
            return _err("VALIDATION_ERROR", "Current key status is invalid", current_status=cur)
        if status not in transitions[cur]:
            return _err("INVALID_TRANSITION", f"Illegal status transition: {cur} -> {status}",
                        from_status=cur, to_status=status)

    # No-op update should not succeed without effect
    changed = False
    new_row = dict(target)

    if owner_label is not None and owner_label != new_row.get("owner_label"):
        new_row["owner_label"] = owner_label
        changed = True
    if metadata is not None and metadata != new_row.get("metadata"):
        new_row["metadata"] = metadata
        changed = True
    if rate_limit_rpm is not None and rate_limit_rpm != new_row.get("rate_limit_rpm"):
        new_row["rate_limit_rpm"] = rate_limit_rpm
        changed = True
    if daily_request_quota is not None and daily_request_quota != new_row.get("daily_request_quota"):
        new_row["daily_request_quota"] = daily_request_quota
        changed = True
    if status is not None and status != new_row.get("status"):
        new_row["status"] = status
        changed = True

    if not changed:
        return _err("CONFLICT", "No changes requested (fields already match)")

    new_row["updated_at"] = _iso(_now())
    api_keys[target_idx] = new_row
    _save("api_keys.json", api_keys)

    return {"api_key_record": new_row}

