            if cdt is None:
                continue
            if cdt >= fdt:
                filtered2.append(r)
        filtered = filtered2
    if tdt is not None:
        filtered2 = []
        for r in filtered:
            cdt = _get_created_dt(r)
            if cdt is None:
                continue
            if cdt <= tdt:
                filtered2.append(r)
        filtered = filtered2

    # Sort
    reverse = (order == "desc")
    if sort == "created_at":
        def keyfn(r):
            dt = _get_created_dt(r)
            # push unparsable to end deterministically
            return (_dt_to_epoch_ms(dt) if dt else (-10**18 if reverse else 10**18), r.get("id") or "")
    else:
        def keyfn(r):
            d = r.get("duration_ms")
            if d is None:
                d = -1
            return (d, r.get("id") or "")

    filtered.sort(key=keyfn, reverse=reverse)

    total = len(filtered)

    # Cursor pagination: opaque base64 of {"offset": int}
    offset = 0
    if cursor is not None:
        if not isinstance(cursor, str) or not cursor:
            return _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided")
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            payload = json.loads(raw.decode("utf-8"))
            off = payload.get("offset")
            if not isinstance(off, int) or off < 0:
                return _err("VALIDATION_ERROR", "cursor is invalid")
            offset = off
        except Exception:
            return _err("VALIDATION_ERROR", "cursor is invalid")

    page = filtered[offset:offset + limit]
    next_off = offset + len(page)
    has_more = next_off < total
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(json.dumps({"offset": next_off}).encode("utf-8")).decode("utf-8").rstrip("=")

    return {
        "data": page,
        "meta": {
            "total": total,
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "sort": sort,
            "order": order,
        }
    }
